var lengthOfLIS = function(nums) {
    const tails = [];
    for (const x of nums) {
        let low = 0, high = tails.length;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (tails[mid] < x) low = mid + 1;
            else high = mid;
        }
        tails[low] = x;
    }
    return tails.length;
};
